206	// Simple warm seed format
207	// magic 0x47574D53 ('GWMS'), version 1, lat/lon in 1e-7 deg, alt mm, date/time
208	struct WarmSeedBinV1 {
209	  uint32_t magic;     // 'GWMS'
210	  uint16_t version;   // 1
211	  int32_t lat_e7;
212	  int32_t lon_e7;
213	  int32_t alt_mm;     // altitude MSL in mm
214	  uint16_t year;
215	  uint8_t month, day, hour, minute, second;
216	};
217	
218	// Age limits in seconds
219	static constexpr uint32_t kSeedMaxAge = 7 * 24 * 3600; // 7 days
220	static constexpr uint32_t kDbdMaxAge = 12 * 3600; // 12 hours
221	
222	static constexpr uint32_t kSeedMagic = 0x47574D53; // GWMS
223	static constexpr uint16_t kSeedVer = 1;
224	static constexpr const char* kSeedDir = "/gnss";
225	static constexpr const char* kSeedPath = "/gnss/warm_seed.bin";
226	static constexpr const char* kDbdPath = "/gnss/dbd_latest.bin";
227	
228	// Forward declarations
229	class GpsConnector;
230	static bool sendMgaIniTimeUtc(GpsConnector* gps, uint16_t year, uint8_t month, uint8_t day, 
231	                              uint8_t hour, uint8_t minute, uint8_t second);
232	static bool sendMgaIniPosLlh(GpsConnector* gps, int32_t lat_1e7, int32_t lon_1e7, int32_t alt_mm);
