234	bool GpsConnector::saveWarmStartSeedToSD() {
235	  // Ensure we have valid data
236	  if (!(data.location_valid && data.date_valid && data.time_valid)) {
237	    M5_LOGW("GPS: Cannot save warm seed — invalid or incomplete GNSS data");
238	    return false;
239	  }
240	
241	  // Ensure directory exists
242	  if (!SD.exists(kSeedDir)) {
243	    if (!SD.mkdir(kSeedDir)) {
244	      M5_LOGE("GPS: Failed to create %s directory on SD", kSeedDir);
245	      return false;
246	    }
247	  }
248	
249	  WarmSeedBinV1 seed{};
250	  seed.magic = kSeedMagic;
251	  seed.version = kSeedVer;
252	  seed.lat_e7 = static_cast<int32_t>(data.latitude * 1e7);
253	  seed.lon_e7 = static_cast<int32_t>(data.longitude * 1e7);
254	  seed.alt_mm = static_cast<int32_t>(data.altitudeMSL * 1000.0);
255	  seed.year = data.year;
256	  seed.month = data.month;
257	  seed.day = data.day;
258	  seed.hour = data.hour;
259	  seed.minute = data.minute;
260	  seed.second = data.second;
261	
262	  File f = SD.open(kSeedPath, FILE_WRITE);
263	  if (!f) {
264	    M5_LOGE("GPS: Failed to open %s for write", kSeedPath);
265	    return false;
266	  }
267	  size_t written = f.write(reinterpret_cast<const uint8_t*>(&seed), sizeof(seed));
268	  f.flush();
269	  f.close();
270	  if (written != sizeof(seed)) {
271	    M5_LOGE("GPS: Failed to write full seed (wrote %u/%u bytes)", (unsigned)written, (unsigned)sizeof(seed));
272	    return false;
273	  }
274	  M5_LOGI("GPS: Warm-start seed saved to %s", kSeedPath);
275	  return true;
276	}
277	
278	bool GpsConnector::injectWarmStartSeedFromSD() {
279	  if (!SD.exists(kSeedPath)) {
280	    M5_LOGI("GPS: No warm-start seed found at %s", kSeedPath);
281	    return false;
282	  }
283	
284	  File f = SD.open(kSeedPath, FILE_READ);
285	  if (!f) {
286	    M5_LOGE("GPS: Failed to open %s for read", kSeedPath);
287	    return false;
288	  }
289	
290	  // Check file age
291	  time_t fileTime = f.getLastWrite();
292	  time_t now = time(nullptr);
293	  if (now > 0 && fileTime > 0 && (now - fileTime) > kSeedMaxAge) {
294	    f.close();
295	    M5_LOGW("GPS: Warm seed too old (%u seconds), skipping injection", (unsigned)(now - fileTime));
296	    return false;
297	  }
298	
299	  WarmSeedBinV1 seed{};
300	  size_t bytesRead = f.read((uint8_t*)&seed, sizeof(seed));
301	  f.close();
302	
303	  if (bytesRead != sizeof(seed)) {
304	    M5_LOGE("GPS: Invalid seed file size: %u bytes (expected %u)", bytesRead, sizeof(seed));
305	    return false;
306	  }
307	
308	  if (seed.magic != 0x47574D53) { // 'GWMS'
309	    M5_LOGE("GPS: Invalid seed magic: 0x%08X", seed.magic);
310	    return false;
311	  }
312	
313	  if (seed.version != 1) {
314	    M5_LOGW("GPS: Unsupported seed version: %u", seed.version);
315	    return false;
316	  }
317	
318	  // Convert back to degrees and meters
319	  double lat = (double)seed.lat_e7 / 1e7;
320	  double lon = (double)seed.lon_e7 / 1e7;
321	  double alt = (double)seed.alt_mm / 1000.0;
322	
323	  M5_LOGI("GPS: Loaded warm seed from SD: %.6f,%.6f,%.1fm %04u-%02u-%02u %02u:%02u:%02u",
324	          lat, lon, alt, seed.year, seed.month, seed.day, seed.hour, seed.minute, seed.second);
325	
326	  // Inject MGA-INI-TIME_UTC
327	  bool timeOk = sendMgaIniTimeUtc(this, seed.year, seed.month, seed.day, seed.hour, seed.minute, seed.second);
328	  if (timeOk) {
329	    M5_LOGI("GPS: MGA-INI-TIME_UTC injected");
330	  } else {
331	    M5_LOGW("GPS: MGA-INI-TIME_UTC injection failed");
332	  }
333	
334	  // Inject MGA-INI-POS_LLH
335	  bool posOk = sendMgaIniPosLlh(this, seed.lat_e7, seed.lon_e7, seed.alt_mm);
336	  if (posOk) {
337	    M5_LOGI("GPS: MGA-INI-POS_LLH injected");
338	  } else {
339	    M5_LOGW("GPS: MGA-INI-POS_LLH injection failed");
340	  }
341	
342	  // Minimal delay during boot
343	  delay(20);
344	
345	  return timeOk && posOk;
346	}
