359	// ---- UBX MGA-DBD dump/restore ----
360	
361	// Pack and send UBX-MGA-INI-TIME_UTC
362	static bool sendMgaIniTimeUtc(GpsConnector* gps, uint16_t year, uint8_t month, uint8_t day, 
363	                              uint8_t hour, uint8_t minute, uint8_t second) {
364	  // UBX-MGA-INI-TIME_UTC payload (24 bytes)
365	  uint8_t payload[24] = {0};
366	  payload[0] = 0x10; // type = TIME_UTC
367	  payload[1] = 0x00; // version
368	  // reserved0[2] = 0
369	  payload[4] = year & 0xFF; payload[5] = (year >> 8) & 0xFF; // year
370	  payload[6] = month; // month
371	  payload[7] = day;   // day
372	  payload[8] = hour;  // hour
373	  payload[9] = minute; // min
374	  payload[10] = second; // sec
375	  // reserved1 = 0
376	  // ns, tAcc, reserved2 = 0 (we don't have sub-second precision)
377	  return gps->sendUBXMessage(0x13, 0x40, payload, sizeof(payload));
378	}
379	
380	// Pack and send UBX-MGA-INI-POS_LLH
381	static bool sendMgaIniPosLlh(GpsConnector* gps, int32_t lat_1e7, int32_t lon_1e7, int32_t alt_mm) {
382	  // UBX-MGA-INI-POS_LLH payload (20 bytes)
383	  uint8_t payload[20] = {0};
384	  payload[0] = 0x01; // type = POS_LLH
385	  payload[1] = 0x00; // version
386	  // reserved0[2] = 0
387	  // lat (4 bytes, little-endian, 1e-7 degrees)
388	  payload[4] = lat_1e7 & 0xFF; payload[5] = (lat_1e7 >> 8) & 0xFF;
389	  payload[6] = (lat_1e7 >> 16) & 0xFF; payload[7] = (lat_1e7 >> 24) & 0xFF;
390	  // lon (4 bytes, little-endian, 1e-7 degrees)
391	  payload[8] = lon_1e7 & 0xFF; payload[9] = (lon_1e7 >> 8) & 0xFF;
392	  payload[10] = (lon_1e7 >> 16) & 0xFF; payload[11] = (lon_1e7 >> 24) & 0xFF;
393	  // alt (4 bytes, little-endian, mm)
394	  payload[12] = alt_mm & 0xFF; payload[13] = (alt_mm >> 8) & 0xFF;
395	  payload[14] = (alt_mm >> 16) & 0xFF; payload[15] = (alt_mm >> 24) & 0xFF;
396	  // posAcc = 0 (we set a large default uncertainty)
397	  uint32_t posAcc = 10000000; // 10km uncertainty in mm
398	  payload[16] = posAcc & 0xFF; payload[17] = (posAcc >> 8) & 0xFF;
399	  payload[18] = (posAcc >> 16) & 0xFF; payload[19] = (posAcc >> 24) & 0xFF;
400	  return gps->sendUBXMessage(0x13, 0x40, payload, sizeof(payload));
401	}
