403	// Read a single UBX frame from _serial_conn. Returns total bytes read into buf, or 0 on timeout/failure.
404	static size_t readOneUbxFrame(HardwareSerial& ser, uint8_t* buf, size_t bufsize, uint32_t timeout_ms) {
405	  const uint32_t start = millis();
406	  enum { SYNC1, SYNC2, CLASS, ID, LEN1, LEN2, PAYLOAD, CK_A, CK_B } state = SYNC1;
407	  uint16_t len = 0; size_t idx = 0; uint8_t ck_a = 0, ck_b = 0; size_t payload_read = 0;
408	  while (millis() - start < timeout_ms) {
409	    if (ser.available() == 0) { delay(1); continue; }
410	    uint8_t b = ser.read();
411	    switch (state) {
412	      case SYNC1:
413	        if (b == 0xB5) { if (idx < bufsize) buf[idx++] = b; state = SYNC2; }
414	        break;
415	      case SYNC2:
416	        if (b == 0x62) { if (idx < bufsize) buf[idx++] = b; state = CLASS; }
417	        else { state = SYNC1; idx = 0; }
418	        break;
419	      case CLASS:
420	        if (idx < bufsize) buf[idx++] = b; ck_a = b; ck_b = ck_a; state = ID; break;
421	      case ID:
422	        if (idx < bufsize) buf[idx++] = b; ck_a += b; ck_b += ck_a; state = LEN1; break;
423	      case LEN1:
424	        if (idx < bufsize) buf[idx++] = b; ck_a += b; ck_b += ck_a; len = b; state = LEN2; break;
425	      case LEN2:
426	        if (idx < bufsize) buf[idx++] = b; ck_a += b; ck_b += ck_a; len |= (uint16_t)b << 8; payload_read = 0; state = (len == 0 ? CK_A : PAYLOAD); break;
427	      case PAYLOAD:
428	        if (idx < bufsize) buf[idx++] = b; ck_a += b; ck_b += ck_a; if (++payload_read >= len) state = CK_A; break;
429	      case CK_A:
430	        if (idx < bufsize) buf[idx++] = b; if (b != ck_a) { state = SYNC1; idx = 0; } else state = CK_B; break;
431	      case CK_B:
432	        if (idx < bufsize) buf[idx++] = b; if (b != ck_b) { state = SYNC1; idx = 0; }
433	        else { return idx; }
434	        break;
435	    }
436	  }
437	  return 0; // timeout
438	}
