440	bool GpsConnector::dumpDatabaseToSD() {
441	  // Ensure directory exists
442	  if (!SD.exists(kSeedDir)) {
443	    if (!SD.mkdir(kSeedDir)) {
444	      M5_LOGE("GPS: Failed to create %s directory on SD", kSeedDir);
445	      return false;
446	    }
447	  }
448	
449	  File f = SD.open(kDbdPath, FILE_WRITE);
450	  if (!f) {
451	    M5_LOGE("GPS: Failed to open %s for write", kDbdPath);
452	    return false;
453	  }
454	
455	  M5_LOGI("GPS: Requesting GNSS database dump to SD...");
456	  // Send UBX-MGA-DBD (class 0x13, id 0x80) with zero-length payload to request dump
457	  if (!sendUBXMessage(0x13, 0x80, nullptr, 0)) {
458	    M5_LOGE("GPS: Failed to send MGA-DBD request");
459	    f.close();
460	    return false;
461	  }
462	
463	  // Read frames for a limited time; write only MGA-DBD frames
464	  const uint32_t overall_start = millis();
465	  uint32_t last_frame_time = overall_start;
466	  uint32_t frames = 0, bytes_written = 0;
467	  uint8_t frame[2048];
468	
469	  while (millis() - last_frame_time < 1000 && millis() - overall_start < 8000) { // 1s quiet or max 8s
470	    size_t n = readOneUbxFrame(_serial_conn, frame, sizeof(frame), 250);
471	    if (n == 0) continue;
472	    last_frame_time = millis();
473	    // Check class/id
474	    if (n >= 6) {
475	      uint8_t cls = frame[2];
476	      uint8_t id  = frame[3];
477	      if (cls == 0x13 && id == 0x80) { // MGA-DBD
478	        size_t w = f.write(frame, n);
479	        if (w != n) { M5_LOGE("GPS: SD write error during DBD dump"); break; }
480	        frames++;
481	        bytes_written += w;
482	      }
483	    }
484	  }
485	  f.flush();
486	  f.close();
487	  if (frames == 0) {
488	    M5_LOGW("GPS: No MGA-DBD frames captured");
489	    return false;
490	  }
491	  M5_LOGI("GPS: DBD dump complete: %u frames, %u bytes to %s", frames, bytes_written, kDbdPath);
492	  return true;
493	}
