495	// Wait for MGA-ACK-DATA0 after sending a frame; return true if seen
496	static bool waitForMgaAck(HardwareSerial& ser, uint32_t timeout_ms) {
497	  uint32_t start = millis();
498	  uint8_t frame[256];
499	  while (millis() - start < timeout_ms) {
500	    size_t n = readOneUbxFrame(ser, frame, sizeof(frame), 50);
501	    if (n >= 6) {
502	      uint8_t cls = frame[2];
503	      uint8_t id  = frame[3];
504	      if (cls == 0x13 && id == 0x60) { // MGA-ACK-DATA0
505	        return true;
506	      }
507	    }
508	  }
509	  return false;
510	}
