512	// Parse concatenated UBX frames from a File and send them one by one
513	bool GpsConnector::restoreDatabaseFromSD() {
514	  if (!SD.exists(kDbdPath)) {
515	    M5_LOGI("GPS: No database dump found at %s", kDbdPath);
516	    return false;
517	  }
518	  File f = SD.open(kDbdPath, FILE_READ);
519	  if (!f) {
520	    M5_LOGE("GPS: Failed to open %s for read", kDbdPath);
521	    return false;
522	  }
523	
524	  // Check file age
525	  time_t fileTime = f.getLastWrite();
526	  time_t now = time(nullptr);
527	  if (now > 0 && fileTime > 0 && (now - fileTime) > kDbdMaxAge) {
528	    f.close();
529	    M5_LOGW("GPS: Database dump too old (%u seconds), skipping restore", (unsigned)(now - fileTime));
530	    return false;
531	  }
532	
533	  size_t fileSize = f.size();
534	  M5_LOGI("GPS: Restoring GNSS database from %s (%u bytes)...", kDbdPath, (unsigned)fileSize);
535	
536	  if (fileSize == 0) {
537	    f.close();
538	    M5_LOGW("GPS: Database file is empty");
539	    return false;
540	  }
541	
542	  size_t frames = 0; size_t bytes = 0; uint8_t b; size_t totalRead = 0;
543	  enum { FIND_SYNC1, FIND_SYNC2, READ_HEADER, READ_PAYLOAD, READ_CKS } state = FIND_SYNC1;
544	  uint8_t header[4]; size_t hidx = 0; uint16_t len = 0; uint16_t pleft = 0; uint8_t ck_a = 0, ck_b = 0;
545	  // Buffer to hold and re-send a full frame
546	  static const size_t MAXF = 2048;
547	  uint8_t frame[MAXF]; size_t fidx = 0;
548	
549	  while (f.available()) {
550	    totalRead++;
551	    int bi = f.read();
552	    if (bi < 0) break;
553	    b = (uint8_t)bi;
554	    switch (state) {
555	      case FIND_SYNC1:
556	        if (b == 0xB5) { fidx = 0; frame[fidx++] = b; state = FIND_SYNC2; }
557	        break;
558	      case FIND_SYNC2:
559	        if (b == 0x62) { frame[fidx++] = b; state = READ_HEADER; hidx = 0; }
560	        else { state = FIND_SYNC1; fidx = 0; }
561	        break;
562	      case READ_HEADER:
563	        header[hidx++] = b; frame[fidx++] = b;
564	        if (hidx == 4) {
565	          ck_a = header[0]; ck_b = ck_a; // class
566	          ck_a += header[1]; ck_b += ck_a; // id
567	          ck_a += header[2]; ck_b += ck_a; // len LSB
568	          ck_a += header[3]; ck_b += ck_a; // len MSB
569	          len = (uint16_t)header[2] | ((uint16_t)header[3] << 8);
570	          pleft = len;
571	          state = (len == 0) ? READ_CKS : READ_PAYLOAD;
572	        }
573	        break;
574	      case READ_PAYLOAD:
575	        frame[fidx++] = b;
576	        ck_a += b; ck_b += ck_a;
577	        if (--pleft == 0) { state = READ_CKS; }
578	        break;
579	      case READ_CKS:
580	        frame[fidx++] = b;
581	        if (fidx == 6 + len + 1) { // just read CK_A
582	          if (b != ck_a) { state = FIND_SYNC1; fidx = 0; break; }
583	        } else if (fidx == 6 + len + 2) { // just read CK_B
584	          if (b != ck_b) { state = FIND_SYNC1; fidx = 0; break; }
585	          // Valid UBX frame complete; send and wait for ACK if it's DBD
586	          uint8_t cls = header[0];
587	          uint8_t id  = header[1];
588	          if (cls == 0x13 && id == 0x80) {
589	            _serial_conn.write(frame, fidx);
590	            _serial_conn.flush();
591	            bytes += fidx; frames++;
592	            // Minimal pacing - don't wait for ACKs during boot
593	            delay(1);
594	          }
595	          // Reset for next frame
596	          state = FIND_SYNC1; fidx = 0;
597	        }
598	        break;
599	    }
600	  }
601	  f.close();
602	  M5_LOGI("GPS: Database restore sent: %u frames, %u bytes (read %u/%u bytes from file)", 
603	          (unsigned)frames, (unsigned)bytes, (unsigned)totalRead, (unsigned)fileSize);
604	  return frames > 0;
605	}
