688	/**
689	 * Read the current dynamic model directly from the GPS module
690	 * @return true if successful, false otherwise
691	 */
692	bool GpsConnector::readDynamicModelFromGPS() {
693	  bool success = false;
694	
695	  if (data.protocolVersionHigh > 0 && data.protocolVersionHigh < 18) {
696	    // u-blox 7: poll UBX-CFG-NAV5 (no payload = poll request)
697	    success = sendUBXMessage(UBX_CLASS_CFG, UBX_ID_CFG_NAV5, nullptr, 0);
698	  } else {
699	    // u-blox 8+ (M8/M9/M10): poll UBX-CFG-VALGET
700	    uint8_t msgPayload[8] = {0};
701	    msgPayload[1] = UBX_CFG_LAYER_RAM;
702	    msgPayload[4] = 0x21; // Key: CFG-NAVSPG-DYNMODEL LSB
703	    msgPayload[5] = 0x00;
704	    msgPayload[6] = 0x11;
705	    msgPayload[7] = 0x20; // MSB
706	    success = sendUBXMessage(UBX_CLASS_CFG, UBX_CFG_VALGET, msgPayload, sizeof(msgPayload));
707	  }
708	
709	  if (success) {
710	    delay(100);
711	    M5_LOGD("GNSS: Current dynamic model (stored): %d", _current_model);
712	  } else {
713	    M5_LOGD("GNSS: Failed to send dynamic model query command");
714	  }
715	
716	  return success;
717	}
