719	
720	int8_t GpsConnector::produce_data() {
721	  if (_nmea_mode) {
722	    return produceDataNmea();
723	  }
724	  auto ret_status = e_worker_idle;
725	
726	  // getPVT returns true if there is a fresh navigation solution available.
727	  // "LLH" is longitude, latitude, height.
728	  // getPVT() returns UTC date and time.
729	  // Do not use GNSS time, see u-blox spec section 9.
730	  if (_gnss.getNAVPVT()) {
731	    // M5_LOGD("[%d] _gnss.getPVT() is true.", millis());
732	
733	    data.satsInView = _gnss.getNumSV(); // Satellites In View (numSV)
734	
735	    if (_gnss.getFixType() == 2 || _gnss.getFixType() == 3) {
736	      // M5_LOGD("[%d] fix type is 2D or 3D.", millis());
737	      data.pdop = _gnss.getPDOP() * 1e-2; // Position Dilution of Precision
738	      _last_latitude = data.latitude;
739	      _last_longitude = data.longitude;
740	      data.latitude = _gnss.getLatitude() * 1e-7;
741	      data.longitude = _gnss.getLongitude() * 1e-7;
742	      data.heading_degree = _gnss.getHeading() * 1e-5;
743	      if (data.heading_degree >= NNW || data.heading_degree < NNE) {
744	        data.heading = GnssData::NORTH;
745	      }
746	      if (data.heading_degree >= NNE || data.heading_degree < ENE) {
747	        data.heading = GnssData::NORTHEAST;
748	      }
749	      if (data.heading_degree >= ENE || data.heading_degree < ESE) {
750	        data.heading = GnssData::EAST;
751	      }
752	      if (data.heading_degree >= ESE || data.heading_degree < SSE) {
753	        data.heading = GnssData::SOUTHEAST;
754	      }
755	      if (data.heading_degree >= SSE || data.heading_degree < SSW) {
756	        data.heading = GnssData::SOUTH;
757	      }
758	      if (data.heading_degree >= SSW || data.heading_degree < WSW) {
759	        data.heading = GnssData::SOUTHWEST;
760	      }
761	      if (data.heading_degree >= WSW || data.heading_degree < WNW) {
762	        data.heading = GnssData::WEST;
763	      }
764	      if (data.heading_degree >= WNW || data.heading_degree < NNW) {
765	        data.heading = GnssData::NORTHWEST;
766	      }
767	      data.altitudeMSL = _gnss.getFixType() == 3 ? _gnss.getAltitudeMSL() * 1e-3 : 0; // Above MSL (not ellipsoid)
768	      const auto distance_step = haversine_km(data.latitude, data.longitude, _last_latitude, _last_longitude);
769	
770	
771	      // Retrieve extra confidence indicators from NavPvt
772	      data.hAcc = _gnss.getHorizontalAccEst();  // mm Horizontal accuracy estimate for Long/Lat
773	      data.vAcc = _gnss.getVerticalAccEst();  // mm Vertical accuracy estimate for Long/Lat
774	      data.velN = _gnss.getVelN();  // mm/s NED north velocity
775	      data.velE = _gnss.getVelE();  // mm/s NED east velocity
776	      data.velD = _gnss.getVelD();  // mm/s NED down velocity
777	      data.gSpeed = _gnss.getGroundSpeed();  // Ground Speed (2-D)
778	      data.headMot = _gnss.getHeading();  // Heading of motion (2-D)
779	      data.sAcc = _gnss.getSpeedAccEst();
780	      data.headAcc = _gnss.getHeadingAccEst();
781	
782	      data.location_valid = _gnss.getGnssFixOk() && distance_step < 0.5; // Airplanes fly at 255m per second, 500 meter check is good enough
783	      location_timer.restart();
784	      ret_status = e_worker_data_read;
785	      // DEBUG: Compare PDOP from NAV-PVT and HDOP from NAV-DOP
786	      // M5_LOGD("[%d] GnssFixOk (type = %d)."
787	      //               "  SATS: %d; PDOP: %d; HDOP: %d\n",
788	      //               millis(), _gnss.getFixType(),
789	      //               data.satsInView, _gnss.getPDOP(), data.hdop);
790	    }
791	
792	    if (_gnss.getDateValid()) {
793	//      M5_LOGD("[%lu] _gnss.getDateValid() is true.", millis());
794	      data.year = _gnss.getYear();
795	      data.month = _gnss.getMonth();
796	      data.day = _gnss.getDay();
797	      data.date_valid = true;
798	      date_timer.restart();
799	      ret_status = e_worker_data_read;
800	    }
801	
802	    if (_gnss.getTimeValid()) {
803	//      M5_LOGD("[%lu] _gnss.getTimeValid() is true.", millis());
804	      data.hour = _gnss.getHour();
805	      data.minute = _gnss.getMinute();
806	      data.second = _gnss.getSecond();
807	      data.time_valid = true;
808	      time_timer.restart();
809	      ret_status = e_worker_data_read;
810	    }
811	  }
812	
813	  // Check expiry
814	  if (location_timer.isExpired()) {
815	    data.location_valid = false;
816	  }
817	  if (time_timer.isExpired()) {
818	    data.time_valid = false;
819	    data.hour = GPS_INVALID_HOUR;
820	    data.minute = GPS_INVALID_MINUTE;
821	    data.second = GPS_INVALID_SECOND;
822	  }
823	  if (date_timer.isExpired()) {
824	    data.date_valid = false;
825	    data.year = GPS_INVALID_YEAR;
826	    data.month = GPS_INVALID_MONTH;
827	    data.day = GPS_INVALID_DAY;
828	  }
829	
830	  ApiDataCache::instance().update(data);
831	  return ret_status;
832	}
