834	/**
835	 * Send a raw UBX message to the GPS module
836	 * @param msgClass UBX message class
837	 * @param msgID UBX message ID
838	 * @param payload Payload data
839	 * @param payloadSize Size of the payload
840	 * @return true if successful, false otherwise
841	 */
842	bool GpsConnector::sendUBXMessage(uint8_t msgClass, uint8_t msgID, const uint8_t* payload, size_t payloadSize) {
843	  // UBX message structure:
844	  // Sync Char 1: 0xB5
845	  // Sync Char 2: 0x62
846	  // Class: 1 byte
847	  // ID: 1 byte
848	  // Length: 2 bytes (little endian)
849	  // Payload: variable length
850	  // Checksum: 2 bytes (CK_A, CK_B)
851	  
852	  // Write sync chars
853	  _serial_conn.write(UBX_SYNC_CHAR_1);
854	  _serial_conn.write(UBX_SYNC_CHAR_2);
855	  
856	  // Write class and ID
857	  _serial_conn.write(msgClass);
858	  _serial_conn.write(msgID);
859	  
860	  // Write length (little endian)
861	  _serial_conn.write(payloadSize & 0xFF);
862	  _serial_conn.write((payloadSize >> 8) & 0xFF);
863	  
864	  // Write payload
865	  if (payload != nullptr && payloadSize > 0) {
866	    _serial_conn.write(payload, payloadSize);
867	  }
868	
869	  // Calculate checksum
870	  uint8_t ck_a = 0, ck_b = 0;
871	
872	  // Add class, ID, and length to checksum
873	  ck_a += msgClass;
874	  ck_b += ck_a;
875	
876	  ck_a += msgID;
877	  ck_b += ck_a;
878	
879	  ck_a += payloadSize & 0xFF;
880	  ck_b += ck_a;
881	
882	  ck_a += (payloadSize >> 8) & 0xFF;
883	  ck_b += ck_a;
884	
885	  // Add payload to checksum
886	  if (payload != nullptr) {
887	    for (size_t i = 0; i < payloadSize; i++) {
888	      ck_a += payload[i];
889	      ck_b += ck_a;
890	    }
891	  }
892	  
893	  // Write checksum
894	  _serial_conn.write(ck_a);
895	  _serial_conn.write(ck_b);
896	  
897	  // Flush the serial buffer
898	  _serial_conn.flush();
899	  
900	  // Wait a bit for the message to be processed
901	  delay(5);
902	  
903	  return true;
904	}
905	
906	/**
907	 * Calculate UBX message checksum
908	 * @param data Data to calculate checksum for
909	 * @param len Length of data
910	 * @param cka Pointer to store CK_A
911	 * @param ckb Pointer to store CK_B
912	 */
913	void GpsConnector::calculateChecksum(const uint8_t* data, size_t len, uint8_t* cka, uint8_t* ckb) {
914	  *cka = 0;
915	  *ckb = 0;
916	  
917	  for (size_t i = 0; i < len; i++) {
918	    *cka += data[i];
919	    *ckb += *cka;
920	  }
921	}
