965	// NMEA fallback mode — used when GPS TX is connected but GPS RX is not,
966	// so only one-way communication (receive NMEA) is possible.
967	// ---------------------------------------------------------------------------
968	
969	double GpsConnector::nmeaCoordToDecimal(const char* coord, char direction) {
970	  double val = atof(coord);
971	  int deg = (int)(val / 100.0);
972	  double min = val - deg * 100.0;
973	  double result = deg + min / 60.0;
974	  if (direction == 'S' || direction == 'W') result = -result;
975	  return result;
976	}
977	
978	bool GpsConnector::parseNmeaSentence(const char* sentence) {
979	  // Validate checksum (XOR of bytes between '$' and '*')
980	  const char* star = strchr(sentence, '*');
981	  if (star != nullptr && strlen(star) >= 3) {
982	    uint8_t calc = 0;
983	    for (const char* p = sentence + 1; p < star; p++) calc ^= (uint8_t)*p;
984	    uint8_t recv = (uint8_t)strtol(star + 1, nullptr, 16);
985	    if (calc != recv) return false;
986	  }
987	
988	  bool isRmc = (strncmp(sentence, "$GPRMC", 6) == 0 || strncmp(sentence, "$GNRMC", 6) == 0);
989	  bool isGga = (strncmp(sentence, "$GPGGA", 6) == 0 || strncmp(sentence, "$GNGGA", 6) == 0);
990	  bool isGsv = (strncmp(sentence, "$GPGSV", 6) == 0 || strncmp(sentence, "$GLGSV", 6) == 0 || strncmp(sentence, "$GNGSV", 6) == 0);
991	  bool isGsa = (strncmp(sentence, "$GPGSA", 6) == 0 || strncmp(sentence, "$GNGSA", 6) == 0);
992	  if (!isRmc && !isGga && !isGsv && !isGsa) return false;
993	
994	  // Determine constellation type char from sentence prefix for GSV
995	  char gnssIdType = 'G'; // default GPS
996	  if (strncmp(sentence, "$GL", 3) == 0) gnssIdType = 'R'; // GLONASS
997	  else if (strncmp(sentence, "$GA", 3) == 0) gnssIdType = 'E'; // Galileo
998	  else if (strncmp(sentence, "$GB", 3) == 0) gnssIdType = 'B'; // BeiDou
999	
1000	  // Copy and strip checksum for field splitting
1001	  char buf[128];
1002	  strncpy(buf, sentence, sizeof(buf) - 1);
1003	  buf[sizeof(buf) - 1] = '\0';
1004	  char* s = strchr(buf, '*');
1005	  if (s) *s = '\0';
1006	
1007	  // Split on commas (GPGSV needs up to 20 fields, GPGSA up to 18)
1008	  char* fields[20] = {nullptr};
1009	  int nf = 0;
1010	  char* p = buf;
1011	  while (nf < 20) {
1012	    fields[nf++] = p;
1013	    p = strchr(p, ',');
1014	    if (!p) break;
1015	    *p++ = '\0';
1016	  }
1017	
1018	  if (isRmc && nf >= 10) {
1019	    // $G?RMC,HHMMSS.ss,A,DDMM.mmm,N,DDDMM.mmm,E,speed,course,DDMMYY,...
1020	    const char* tstr = fields[1];
1021	    const char* stat = fields[2];
1022	    const char* lat  = fields[3];
1023	    const char* ns   = fields[4];
1024	    const char* lon  = fields[5];
1025	    const char* ew   = fields[6];
1026	    const char* spd  = fields[7];
1027	    const char* crs  = fields[8];
1028	    const char* dstr = fields[9];
1029	
1030	    if (strlen(tstr) >= 6) {
1031	      char tmp[3] = {tstr[0], tstr[1], '\0'}; data.hour   = atoi(tmp);
1032	      tmp[0] = tstr[2]; tmp[1] = tstr[3];     data.minute = atoi(tmp);
1033	      tmp[0] = tstr[4]; tmp[1] = tstr[5];     data.second = atoi(tmp);
1034	      data.time_valid = true;
1035	      time_timer.restart();
1036	    }
1037	    if (strlen(dstr) >= 6) {
1038	      char tmp[3] = {dstr[0], dstr[1], '\0'}; data.day   = atoi(tmp);
1039	      tmp[0] = dstr[2]; tmp[1] = dstr[3];     data.month = atoi(tmp);
1040	      tmp[0] = dstr[4]; tmp[1] = dstr[5];     data.year  = 2000 + atoi(tmp);
1041	      data.date_valid = true;
1042	      date_timer.restart();
1043	    }
1044	    if (stat[0] == 'A' && strlen(lat) > 0 && strlen(lon) > 0) {
1045	      double new_lat = nmeaCoordToDecimal(lat, ns[0]);
1046	      double new_lon = nmeaCoordToDecimal(lon, ew[0]);
1047	      // Skip distance sanity check on first fix (last position is 0,0)
1048	      bool first_fix = (_last_latitude == 0.0 && _last_longitude == 0.0);
1049	      const auto dist = haversine_km(new_lat, new_lon, _last_latitude, _last_longitude);
1050	      _last_latitude  = data.latitude;
1051	      _last_longitude = data.longitude;
1052	      data.latitude  = new_lat;
1053	      data.longitude = new_lon;
1054	      data.gSpeed    = (int32_t)(atof(spd) * 514.444); // knots → mm/s
1055	      data.heading_degree = strlen(crs) > 0 ? atof(crs) : 0.0;
1056	      data.location_valid = first_fix || (dist < 0.5);
1057	      location_timer.restart();
1058	      return true;
1059	    }
1060	  }
1061	
1062	  if (isGga && nf >= 10) {
1063	    // $G?GGA,time,lat,N,lon,E,quality,nsats,hdop,alt,M,...
1064	    const char* qual  = fields[6];
1065	    const char* nsats = fields[7];
1066	    const char* hdop  = fields[8];
1067	    const char* alt   = fields[9];
1068	    if (qual[0] != '0' && strlen(nsats) > 0) {
1069	      data.satsInView = atoi(nsats);
1070	      data.numSV      = data.satsInView;
1071	      data.pdop       = strlen(hdop) > 0 ? atof(hdop) : 0.0;
1072	      data.altitudeMSL = strlen(alt) > 0 ? atof(alt) : 0.0;
1073	      return true;
1074	    }
1075	  }
1076	
1077	  if (isGsv && nf >= 4) {
1078	    // $G?GSV,numMsgs,msgNum,numSV,sv1,elev1,azim1,cno1[,...]*cs
1079	    int totalMsgs = atoi(fields[1]);
1080	    int msgNum = atoi(fields[2]);
1081	    if (msgNum == 1) {
1082	      // First message: reset accumulator
1083	      data.nmea_sat_count = 0;
1084	      data.numSV = atoi(fields[3]); // total sats in view (not used in fix)
1085	      // satsInView is set from GPGSA (used-in-fix count) — don't overwrite here
1086	    }
1087	    // Each message carries up to 4 sats starting at field index 4
1088	    for (int i = 0; i < 4 && data.nmea_sat_count < GnssData::NMEA_MAX_SATS; i++) {
1089	      int base = 4 + i * 4;
1090	      if (base + 3 >= nf || !fields[base] || strlen(fields[base]) == 0) break;
1091	      GnssData::NmeaSatEntry& sat = data.nmea_sats[data.nmea_sat_count++];
1092	      sat.svId       = (uint8_t)atoi(fields[base]);
1093	      sat.elev       = (int8_t)atoi(fields[base + 1]);
1094	      sat.azim       = (int16_t)atoi(fields[base + 2]);
1095	      sat.cno        = (fields[base + 3] && strlen(fields[base + 3]) > 0)
1096	                       ? (uint8_t)atoi(fields[base + 3]) : 0;
1097	      sat.gnssIdType = gnssIdType;
1098	      // Mark as used if svId is in the GPGSA used list
1099	      sat.svUsed = false;
1100	      for (uint8_t j = 0; j < _nmea_used_count; j++) {
1101	        if (_nmea_used_svids[j] == sat.svId) { sat.svUsed = true; break; }
1102	      }
1103	    }
1104	    if (msgNum == totalMsgs) {
1105	      data.nmea_gsv_cycle++; // signal a complete GPGSV cycle to NavsatCollector
1106	    }
1107	    return true;
1108	  }
1109	
1110	  if (isGsa && nf >= 3) {
1111	    // $G?GSA,mode,fix,sv1..sv12,pdop,hdop,vdop
1112	    // fields[3..14] are SV IDs used (may be blank)
1113	    _nmea_used_count = 0;
1114	    for (int i = 3; i <= 14 && i < nf && _nmea_used_count < 12; i++) {
1115	      if (fields[i] && strlen(fields[i]) > 0) {
1116	        _nmea_used_svids[_nmea_used_count++] = (uint8_t)atoi(fields[i]);
1117	      }
1118	    }
1119	    // In NMEA mode satsInView reflects sats used in fix (consistent with UBX NAV-PVT numSV)
1120	    data.satsInView = _nmea_used_count;
1121	    // Update svUsed flag for already-collected satellite entries
1122	    for (uint8_t i = 0; i < data.nmea_sat_count; i++) {
1123	      data.nmea_sats[i].svUsed = false;
1124	      for (uint8_t j = 0; j < _nmea_used_count; j++) {
1125	        if (_nmea_used_svids[j] == data.nmea_sats[i].svId) {
1126	          data.nmea_sats[i].svUsed = true;
1127	          break;
1128	        }
1129	      }
1130	    }
1131	    return true;
1132	  }
1133	
1134	  return false;
1135	}
1136	
1137	int8_t GpsConnector::produceDataNmea() {
1138	  auto ret_status = e_worker_idle;
1139	  static bool first_fix_logged = false;
1140	
1141	  while (_serial_conn.available()) {
1142	    char c = (char)_serial_conn.read();
1143	    if (c == '$') {
1144	      _nmea_len = 0;
1145	      _nmea_buf[_nmea_len++] = c;
1146	    } else if (c == '\n' || c == '\r') {
1147	      if (_nmea_len > 6) {
1148	        _nmea_buf[_nmea_len] = '\0';
1149	        if (parseNmeaSentence(_nmea_buf)) {
1150	          ret_status = e_worker_data_read;
1151	          if (!first_fix_logged && data.location_valid) {
1152	            first_fix_logged = true;
1153	            M5_LOGI("GNSS: NMEA fix — lat=%.5f lon=%.5f alt=%.1fm sats=%d",
1154	                    data.latitude, data.longitude, data.altitudeMSL, data.satsInView);
1155	          }
1156	        }
1157	      }
1158	      _nmea_len = 0;
1159	    } else if (_nmea_len > 0 && _nmea_len < (uint8_t)(sizeof(_nmea_buf) - 1)) {
1160	      _nmea_buf[_nmea_len++] = c;
1161	    }
1162	  }
1163	
1164	  if (location_timer.isExpired()) data.location_valid = false;
1165	  if (time_timer.isExpired()) {
1166	    data.time_valid = false;
1167	    data.hour = GPS_INVALID_HOUR;
1168	    data.minute = GPS_INVALID_MINUTE;
1169	    data.second = GPS_INVALID_SECOND;
1170	  }
1171	  if (date_timer.isExpired()) {
1172	    data.date_valid = false;
1173	    data.year  = GPS_INVALID_YEAR;
1174	    data.month = GPS_INVALID_MONTH;
1175	    data.day   = GPS_INVALID_DAY;
1176	  }
1177	
1178	  ApiDataCache::instance().update(data);
1179	  return ret_status;
1180	}
